import{_ as o,o as r,c as s,a2 as a}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"즐겨찾기","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/favorites.md","filePath":"ko-KR/user-guide/settings/favorites.md","lastUpdated":1787586465000}'),e={name:"ko-KR/user-guide/settings/favorites.md"};function n(i,t,l,g,d,c){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="즐겨찾기" tabindex="-1">즐겨찾기 <a class="header-anchor" href="#즐겨찾기" aria-label="Permalink to &quot;즐겨찾기&quot;">​</a></h1><p>즐겨찾기는 자주 사용하는 폴더, 파일, 스크립트 또는 웹 URL을 고정 등록하여 전용 사용자 지정 이름과 최우선 검색 순위를 부여하는 기능입니다. 설정 경로는 <strong>설정 → 즐겨찾기</strong>입니다.</p><h2 id="_1-즐겨찾기-항목-추가" tabindex="-1">1. 즐겨찾기 항목 추가 <a class="header-anchor" href="#_1-즐겨찾기-항목-추가" aria-label="Permalink to &quot;1. 즐겨찾기 항목 추가&quot;">​</a></h2><p>상단 등록 폼에서:</p><ul><li><strong>표시 이름</strong>: 선택 사항. 비워둘 경우 대상이 로컬 경로이면 해당 파일이나 폴더의 이름이 자동으로 채워집니다.</li><li><strong>대상 경로</strong>: 로컬 파일/폴더의 절대 경로 또는 <code>http://</code> / <code>https://</code>로 시작하는 웹 URL 입력.</li><li><strong>찾아보기</strong>: <strong>폴더 찾아보기</strong> 또는 <strong>파일 찾아보기</strong>를 클릭하여 네이티브 파일 선택기로 직접 지정.</li><li><strong>추가</strong>: 유효한 경로를 입력한 후 <strong>추가</strong> 버튼을 클릭하여 저장.</li></ul><h2 id="_2-목록-관리-및-드래그-앤-드롭-정렬" tabindex="-1">2. 목록 관리 및 드래그 앤 드롭 정렬 <a class="header-anchor" href="#_2-목록-관리-및-드래그-앤-드롭-정렬" aria-label="Permalink to &quot;2. 목록 관리 및 드래그 앤 드롭 정렬&quot;">​</a></h2><p>등록된 항목은 하단 목록에 표시되며 다음과 같이 관리할 수 있습니다.</p><ul><li><strong>6점 드래그 핸들 정렬</strong>: 각 행 좌측의 6점 핸들을 드래그하여 순서를 변경하거나 우측의 <strong>위로 이동</strong> / <strong>아래로 이동</strong> 버튼을 사용할 수 있습니다. 이 순서는 검색 결과와 퀵 내비게이션 메뉴의 노출 우선순위에 즉시 반영됩니다.</li><li><strong>편집</strong>: 클릭 시 해당 항목 데이터가 상단 폼으로 다시 로드되어 수정 후 저장할 수 있습니다.</li><li><strong>삭제</strong>: 즐겨찾기에서 항목을 안전하게 제거합니다.</li></ul><h2 id="_3-검색-재호출-및-시각적-표시" tabindex="-1">3. 검색 재호출 및 시각적 표시 <a class="header-anchor" href="#_3-검색-재호출-및-시각적-표시" aria-label="Permalink to &quot;3. 검색 재호출 및 시각적 표시&quot;">​</a></h2><ul><li><strong>별표 배지 (★)</strong>: 검색 결과에 즐겨찾기 항목이 일치하면 경로 옆에 눈에 띄는 <strong>★</strong> 배지가 표시됩니다.</li><li><strong>커스텀 별칭 검색</strong>: 깊숙한 경로에 기억하기 쉬운 별칭을 부여할 수 있습니다(예: <code>D:\\Workspace\\2026\\Q1\\Financial\\Summary.xlsx</code>에 <code>재무총괄</code> 지정). 검색창에 해당 이름을 입력하면 즉시 호출됩니다.</li><li><strong>다중 인터페이스 연동</strong>: 등록된 즐겨찾기는 <a href="./../hotkeys.html#3-퀵-내비게이션-마우스-트리거"><strong>퀵 내비게이션</strong></a> 메뉴 및 <a href="./quick-panel.html#4-플러그인-동적-탭-plugin-tabs"><strong>퀵 패널</strong></a>의 &quot;즐겨찾기&quot; 탭에 자동 동기화됩니다.</li></ul>',10)])])}const _=o(e,[["render",n]]);export{h as __pageData,_ as default};
